INSERT INTO `language_how_titles` (`id`, `language_id`, `title`, `description`) VALUES
(40, 41, 'Find a TikTok:', 'Open the TikTok website or application. Choose the profile, story, or video where you want to become a spy! Make sure you have a fast internet connection and the selection is right.'),
(56, 48, 'Trova un TT', '- Apri l\'app TikTok sul tuo dispositivo mobile. Scorri fino a trovare il video che desideri salvare. Riproduci il video per confermare che sia quello giusto.'),
(57, 48, 'Copia il link', '- Tocca il pulsante Condividi situato sul lato destro dello schermo. Seleziona Copia link dal menu. Controlla gli appunti per assicurarti che l\'URL sia stato copiato correttamente.'),
(58, 50, 'Téléchargeur de vidéos TikTok', 'Téléchargeur de vidéos TikTok'),
(59, 41, 'Copy the Link:', 'Press “Share” and copy the link for further processing. If you are unable to copy the link, press and hold it.'),
(60, 41, 'Paste the Link:', 'Open TikTokio Viewer tool, paste the link and wait!'),
(61, 41, 'Complete the Process:', 'Processing starts within a few seconds, and you’re ready to get what you want!'),
(62, 41, 'View Online:', 'Tap the play button to view the profile as a spy, then repeat the process for other formats, such as videos and stories.'),
(63, 60, 'Găsiți un tiktok', 'Deschide site-ul sau aplicația TikTok. Alege profilul, povestea sau videoclipul în care vrei să devii spion! Asigură-te că ai internet rapid și că selecția este corectă.'),
(64, 60, 'Copiați linkul', 'Apăsați „Share” și copiați linkul pentru procesare ulterioară. Dacă nu puteți copia linkul, apăsați Long pe acesta.'),
(65, 60, 'Lipiți legătura', 'Deschideți instrumentul Tiktokio.Mobi Viewer, lipiți linkul și așteptați!'),
(66, 60, 'Finalizați procesul', 'Prelucrarea începe în câteva secunde și sunteți gata să obțineți ceea ce doriți!'),
(67, 60, 'Vizualizați online', 'Atingeți jocul pentru a vizualiza profilul ca un spion și repetați procesul pentru alte formate precum videoclipuri și povești.'),
(68, 51, 'Trouver un TikTok', 'Ouvrez le site Web ou l\'application TikTok. Choisissez le profil, l\'histoire ou la vidéo dans laquelle vous souhaitez devenir un espion ! Assurez-vous d’avoir une connexion Internet rapide et que la sélection est bonne.'),
(69, 51, 'Copiez le lien', 'Appuyez sur \"Partager\" et copiez le lien pour un traitement ultérieur. Si vous ne parvenez pas à copier le lien, appuyez longuement dessus.'),
(70, 51, 'Collez le lien', 'Ouvrez l\'outil TikTokio.Mobi Viewer, collez le lien et attendez !'),
(71, 51, 'Terminez le processus', 'Le traitement démarre en quelques secondes et vous êtes prêt à obtenir ce que vous voulez !'),
(72, 51, 'Voir en ligne', 'Appuyez sur Play pour afficher le profil en tant qu\'espion et répétez le processus pour d\'autres formats comme les vidéos et les histoires.'),
(73, 54, 'Trova un TikTok', 'Apri il sito web o l\'applicazione TikTok. Scegli il profilo, la storia o il video in cui vuoi diventare una spia! Assicurati di avere una connessione Internet veloce e che la selezione sia giusta.'),
(74, 54, 'Copia il collegamento', 'Premi \"Condividi\" e copia il collegamento per un\'ulteriore elaborazione. Se non riesci a copiare il collegamento, premi a lungo su di esso.'),
(75, 54, 'Incolla il collegamento', 'Apri lo strumento TikTokio.Mobi Viewer, incolla il collegamento e attendi!'),
(76, 54, 'Completa il processo', 'L\'elaborazione inizia in pochi secondi e sei pronto per ottenere ciò che desideri!'),
(77, 54, 'Visualizza in linea', 'Tocca la riproduzione per visualizzare il profilo come spia e ripeti la procedura per altri formati come video e storie.'),
(78, 55, 'Encuentra un TikTok:', 'Abra el sitio web o la aplicación de TikTok. ¡Elige el perfil, historia o vídeo en el que quieres convertirte en espía! Asegúrese de tener una Internet rápida y de que la selección sea la correcta.'),
(79, 55, 'Copia el enlace:', 'Presione \"Compartir\" y copie el enlace para su posterior procesamiento. Si no puede copiar el enlace, manténgalo presionado.'),
(80, 55, 'Pega el enlace:', 'Abra la herramienta TikTokio.Mobi Viewer, pegue el enlace y espere.'),
(81, 55, 'Completa el proceso:', 'El procesamiento comienza en unos segundos y ¡está listo para obtener lo que desea!'),
(82, 55, 'Ver en línea:', 'Toca reproducir para ver el perfil como espía y repite el proceso para otros formatos como videos e historias.'),
(83, 56, 'Temukan TikTok:', 'Buka website atau aplikasi TikTok. Pilih profil, cerita, atau video di mana Anda ingin menjadi mata-mata! Pastikan Anda memiliki internet yang cepat dan pilihan yang tepat.'),
(84, 56, 'Salin Tautan:', 'Tekan \"Bagikan\" dan salin tautan untuk diproses lebih lanjut. Jika Anda tidak dapat menyalin tautan, tekan lama tautan tersebut.'),
(85, 56, 'Tempel Tautan:', 'Buka alat TikTokio.Mobi Viewer, tempel tautannya dan tunggu!'),
(86, 56, 'Selesaikan Prosesnya:', 'Pemrosesan dimulai dalam beberapa detik, dan Anda siap mendapatkan apa yang Anda inginkan!'),
(87, 56, 'Lihat Daring:', 'Ketuk putar untuk melihat profil sebagai mata-mata dan ulangi proses untuk format lain seperti video dan cerita.'),
(88, 57, 'Bir TikTok bulun:', 'TikTok web sitesini veya uygulamasını açın. Casus olmak istediğiniz profili, hikayeyi veya videoyu seçin! Hızlı bir internete sahip olduğunuzdan ve seçimin doğru olduğundan emin olun.'),
(89, 57, 'Bağlantıyı kopyalayın:', '\"Paylaş\"a basın ve daha ileri işlemler için bağlantıyı kopyalayın. Bağlantıyı kopyalayamıyorsanız, üzerine uzun basın.'),
(90, 57, 'Bağlantıyı yapıştırın:', 'TikTokio.Mobi Viewer aracını açın, bağlantıyı yapıştırın ve bekleyin!'),
(91, 57, 'İşlemi Tamamlayın:', 'İşleme birkaç saniye içinde başlar ve istediğinizi almaya hazırsınız!'),
(92, 57, 'Çevrimiçi Görüntüle:', 'Profili casus olarak görüntülemek ve işlemi videolar ve hikayeler gibi diğer formatlar için tekrarlamak için oynat\'a dokunun.'),
(93, 58, 'ابحث عن تيك توك:', 'افتح موقع أو تطبيق TikTok. اختر الملف الشخصي أو القصة أو الفيديو الذي تريد أن تصبح جاسوسًا فيه! تأكد من أن لديك إنترنت سريع وأن الاختيار صحيح.'),
(94, 58, 'انسخ الرابط:', 'اضغط على \"مشاركة\" وانسخ الرابط لمزيد من المعالجة. إذا لم تتمكن من نسخ الرابط، فاضغط عليه لفترة طويلة.'),
(95, 58, 'الصق الرابط:', 'افتح أداة TikTokio.Mobi Viewer، والصق الرابط وانتظر!'),
(96, 58, 'أكمل العملية:', 'تبدأ المعالجة خلال ثوانٍ قليلة، وستكون جاهزًا للحصول على ما تريد!'),
(97, 58, 'عرض على الإنترنت:', 'اضغط على التشغيل لعرض الملف الشخصي كجاسوس وكرر العملية لتنسيقات أخرى مثل مقاطع الفيديو والقصص.'),
(98, 59, 'Encontre um TikTok:', 'Abra o site ou aplicativo TikTok. Escolha o perfil, história ou vídeo onde deseja se tornar um espião! Certifique-se de ter uma internet rápida e de que a seleção está correta.'),
(99, 59, 'Copie o Link:', 'Pressione \"Compartilhar\" e copie o link para processamento posterior. Se você não conseguir copiar o link, pressione-o longamente.'),
(100, 59, 'Cole o link:', 'Abra a ferramenta TikTokio.Mobi Viewer, cole o link e aguarde!'),
(101, 59, 'Conclua o processo:', 'O processamento começa em alguns segundos e você está pronto para conseguir o que deseja!'),
(102, 59, 'Ver on-line:', 'Toque no play para visualizar o perfil como espião e repita o processo para outros formatos como vídeos e stories.'),
(103, 61, 'Zoek een TikTok:', 'Open de TikTok-website of -applicatie. Kies het profiel, het verhaal of de video waarin je spion wilt worden! Zorg ervoor dat je snel internet hebt en dat de selectie klopt.'),
(104, 61, 'Kopieer de link:', 'Druk op \"Delen\" en kopieer de link voor verdere verwerking. Als u de link niet kunt kopiëren, drukt u er lang op.'),
(105, 61, 'Plak de link:', 'Open de TikTokio.Mobi Viewer-tool, plak de link en wacht!'),
(106, 61, 'Voltooi het proces:', 'De verwerking begint binnen een paar seconden en u bent klaar om te krijgen wat u wilt!'),
(107, 61, 'Online bekijken:', 'Tik op het afspelen om het profiel als spion te bekijken en herhaal het proces voor andere formaten zoals video\'s en verhalen.'),
(108, 62, 'Знайти тикток:', 'Відкрийте веб -сайт або додаток Tiktok. Виберіть профіль, історію чи відео, де ви хочете стати шпигуном! Переконайтеся, що у вас швидкий Інтернет, і вибір правильний.'),
(109, 62, 'Скопіюйте посилання:', 'Натисніть \"Поділитися\" та скопіюйте посилання для подальшої обробки. Якщо ви не можете скопіювати посилання, тоді натисніть на нього.'),
(110, 62, 'Вставте посилання:', 'Відкрийте інструмент перегляду Tiktokio.mobi, вставте посилання та зачекайте!'),
(111, 62, 'Завершіть процес:', 'Обробка починається протягом декількох секунд, і ви готові отримати те, що хочете!'),
(112, 62, 'Переглянути в Інтернеті:', 'Натисніть на гру, щоб переглянути профіль як шпигуна та повторіть процес для інших форматів, таких як відео та історії.'),
(113, 63, 'Cari tiktok:', 'Buka laman web atau aplikasi Tiktok. Pilih profil, cerita, atau video di mana anda ingin menjadi pengintip! Pastikan anda mempunyai internet yang cepat dan pemilihannya betul.'),
(114, 63, 'Salin pautan:', 'Tekan \"Kongsi\" dan salin pautan untuk pemprosesan selanjutnya. Jika anda tidak dapat menyalin pautan, kemudian tekan lama.'),
(115, 63, 'Tampal pautan:', 'Buka Tiktokio.Mobi Viewer Tool, Tampalkan pautan dan tunggu!'),
(116, 63, 'Lengkapkan proses:', 'Pemprosesan bermula dalam masa beberapa saat, dan anda sudah bersedia untuk mendapatkan apa yang anda mahukan!'),
(117, 63, 'Lihat dalam talian:', 'Ketik pada permainan untuk melihat profil sebagai mata -mata dan ulangi proses untuk format lain seperti video dan cerita.'),
(118, 64, 'Znajdź TikToka:', 'Otwórz witrynę lub aplikację TikTok. Wybierz profil, historię lub film, w którym chcesz zostać szpiegiem! Upewnij się, że masz szybki internet i że wybór jest właściwy.'),
(119, 64, 'Skopiuj link:', 'Naciśnij „Udostępnij” i skopiuj link do dalszego przetwarzania. Jeśli nie możesz skopiować linku, naciśnij go długo.'),
(120, 64, 'Wklej link:', 'Otwórz narzędzie TikTokio.Mobi Viewer, wklej link i czekaj!'),
(121, 64, 'Zakończ proces:', 'Przetwarzanie rozpoczyna się w ciągu kilku sekund i możesz otrzymać to, czego chcesz!'),
(122, 64, 'Zobacz online:', 'Kliknij przycisk odtwarzania, aby wyświetlić profil jako szpieg, i powtórz proces w przypadku innych formatów, takich jak filmy i historie.'),
(123, 65, 'Tìm một TikTok:', 'Mở trang web hoặc ứng dụng TikTok. Chọn hồ sơ, câu chuyện hoặc video mà bạn muốn trở thành điệp viên! Hãy chắc chắn rằng bạn có Internet nhanh và lựa chọn đúng.'),
(124, 65, 'Sao chép liên kết:', 'Nhấn \"Chia sẻ\" và sao chép liên kết để xử lý thêm. Nếu bạn không thể sao chép liên kết, hãy nhấn và giữ liên kết đó.'),
(125, 65, 'Dán liên kết:', 'Mở công cụ TikTokio.Mobi Viewer, dán link và chờ đợi!'),
(126, 65, 'Hoàn tất quy trình:', 'Quá trình xử lý bắt đầu trong vòng vài giây và bạn đã sẵn sàng đạt được điều mình muốn!'),
(127, 65, 'Xem trực tuyến:', 'Nhấn vào phần phát để xem hồ sơ dưới dạng gián điệp và lặp lại quy trình cho các định dạng khác như video và câu chuyện.'),
(128, 66, 'Найдите ТикТок:', 'Откройте сайт или приложение TikTok. Выберите профиль, историю или видео, где вы хотите стать шпионом! Убедитесь, что у вас быстрый Интернет и выбор правильный.'),
(129, 66, 'Скопируйте ссылку:', 'Нажмите «Поделиться» и скопируйте ссылку для дальнейшей обработки. Если у вас не получается скопировать ссылку, нажмите и удерживайте ее.'),
(130, 66, 'Вставьте ссылку:', 'Откройте инструмент TikTokio.Mobi Viewer, вставьте ссылку и ждите!'),
(131, 66, 'Завершите процесс:', 'Обработка начнется через несколько секунд, и вы готовы получить то, что хотите!'),
(132, 66, 'Посмотреть онлайн:', 'Нажмите на воспроизведение, чтобы просмотреть профиль шпиона, и повторите процесс для других форматов, таких как видео и истории.'),
(133, 67, '틱톡 찾기:', 'TikTok 웹사이트나 애플리케이션을 엽니다. 스파이가 되고 싶은 프로필, 스토리, 동영상을 선택하세요! 인터넷 속도가 빠르고 선택이 올바른지 확인하세요.'),
(134, 67, '링크 복사:', '\"공유\"를 누르고 추가 처리를 위해 링크를 복사하세요. 링크 복사가 안되면 길게 눌러주세요.'),
(135, 67, '링크 붙여넣기:', 'TikTokio.Mobi 뷰어 도구를 열고 링크를 붙여넣은 후 기다리세요!'),
(136, 67, '프로세스를 완료하십시오:', '몇 초 내에 처리가 시작되며 원하는 것을 얻을 준비가 된 것입니다!'),
(137, 67, '온라인으로 보기:', '재생을 탭하면 프로필을 스파이로 볼 수 있고 비디오 및 스토리와 같은 다른 형식에 대해서도 프로세스를 반복할 수 있습니다.'),
(138, 68, 'TikTok を探す:', 'TikTok Web サイトまたはアプリケーションを開きます。スパイになりたいプロフィール、ストーリー、またはビデオを選択してください。インターネットが高速であることと、選択が正しいことを確認してください。'),
(139, 68, 'リンクをコピーします:', '[共有] を押してリンクをコピーし、さらに処理します。リンクをコピーできない場合は、リンクを長押しします。'),
(140, 68, 'リンクを貼り付けます:', 'TikTokio.Mobi Viewer ツールを開き、リンクを貼り付けて待ちます。'),
(141, 68, 'プロセスを完了します。', '数秒以内に処理が開始され、欲しいものを手に入れる準備が整います。'),
(142, 68, 'オンラインで見る:', '再生をタップしてプロフィールをスパイとして表示し、ビデオやストーリーなどの他の形式に対してこのプロセスを繰り返します。'),
(143, 69, 'একটি টিকটোক সন্ধান করুন:', 'টিকটোক ওয়েবসাইট বা অ্যাপ্লিকেশনটি খুলুন। আপনি গুপ্তচর হতে চান যেখানে প্রোফাইল, গল্প বা ভিডিও চয়ন করুন! আপনার একটি দ্রুত ইন্টারনেট রয়েছে এবং নির্বাচনটি সঠিক তা নিশ্চিত করুন।'),
(144, 69, 'লিঙ্কটি অনুলিপি করুন:', '\"শেয়ার\" টিপুন এবং আরও প্রক্রিয়াজাতকরণের জন্য লিঙ্কটি অনুলিপি করুন। আপনি যদি লিঙ্কটি অনুলিপি করতে অক্ষম হন তবে এটিতে দীর্ঘ টিপুন।'),
(145, 69, 'লিঙ্কটি আটকান:', 'টিকটোকিও.মোবি ভিউয়ার টুলটি খুলুন, লিঙ্কটি আটকান এবং অপেক্ষা করুন!'),
(146, 69, 'প্রক্রিয়াটি সম্পূর্ণ করুন:', 'প্রক্রিয়াজাতকরণ কয়েক সেকেন্ডের মধ্যে শুরু হয় এবং আপনি যা চান তা পেতে প্রস্তুত!'),
(147, 69, 'অনলাইন দেখুন:', 'স্পাই হিসাবে প্রোফাইলটি দেখতে প্লেটিতে আলতো চাপুন এবং ভিডিও এবং গল্পগুলির মতো অন্যান্য ফর্ম্যাটগুলির জন্য প্রক্রিয়াটি পুনরাবৃত্তি করুন।'),
(148, 70, 'ابحث عن تيك توك:', 'افتح موقع أو تطبيق TikTok. اختر الملف الشخصي أو القصة أو الفيديو الذي تريد أن تصبح جاسوسًا فيه! تأكد من أن لديك اتصال إنترنت سريع وأن الاختيار صحيح.'),
(149, 70, 'انسخ الرابط:', 'اضغط على \"مشاركة\" وانسخ الرابط لمزيد من المعالجة. إذا لم تتمكن من نسخ الرابط، فاضغط عليه مع الاستمرار.'),
(150, 70, 'الصق الرابط:', 'افتح أداة TikTokio Viewer، والصق الرابط وانتظر!'),
(151, 70, 'أكمل العملية:', 'تبدأ المعالجة خلال ثوانٍ قليلة، وستكون جاهزًا للحصول على ما تريد!'),
(152, 70, 'عرض على الإنترنت:', 'اضغط على زر التشغيل لعرض الملف الشخصي كجاسوس، ثم كرر العملية مع التنسيقات الأخرى، مثل مقاطع الفيديو والقصص.'),
(153, 71, 'Tìm một TikTok:', 'Mở trang web hoặc ứng dụng TikTok. Chọn hồ sơ, câu chuyện hoặc video mà bạn muốn trở thành điệp viên! Đảm bảo bạn có kết nối Internet nhanh và lựa chọn đúng.'),
(154, 71, 'Sao chép liên kết:', 'Nhấn “Chia sẻ” và sao chép liên kết để xử lý thêm. Nếu bạn không thể sao chép liên kết, hãy nhấn và giữ liên kết đó.'),
(155, 71, 'Dán liên kết:', 'Mở công cụ TikTokio Viewer, dán link và chờ đợi!'),
(156, 71, 'Hoàn tất quy trình:', 'Quá trình xử lý bắt đầu trong vòng vài giây và bạn đã sẵn sàng đạt được điều mình muốn!'),
(157, 71, 'Xem trực tuyến:', 'Nhấn vào nút phát để xem hồ sơ dưới dạng gián điệp, sau đó lặp lại quy trình cho các định dạng khác, chẳng hạn như video và câu chuyện.'),
(158, 74, 'Temukan TikTok:', 'Buka website atau aplikasi TikTok. Pilih profil, cerita, atau video di mana Anda ingin menjadi mata-mata! Pastikan Anda memiliki koneksi internet yang cepat dan pilihan yang tepat.'),
(159, 74, 'Salin Tautan:', 'Tekan “Bagikan” dan salin tautan untuk diproses lebih lanjut. Jika Anda tidak dapat menyalin tautan, tekan dan tahan.'),
(160, 74, 'Tempel Tautan:', 'Buka alat Penampil TikTokio, tempel tautannya dan tunggu!'),
(161, 74, 'Selesaikan Prosesnya:', 'Pemrosesan dimulai dalam beberapa detik, dan Anda siap mendapatkan apa yang Anda inginkan!'),
(162, 74, 'Lihat Daring:', 'Ketuk tombol putar untuk melihat profil sebagai mata-mata, lalu ulangi proses untuk format lain, seperti video dan cerita.'),
(163, 75, 'Encuentra un TikTok:', 'Abra el sitio web o la aplicación de TikTok. ¡Elige el perfil, historia o vídeo en el que quieres convertirte en espía! Asegúrese de tener una conexión a Internet rápida y de que la selección sea correcta.'),
(164, 75, 'Copia el enlace:', 'Presione \"Compartir\" y copie el enlace para su posterior procesamiento. Si no puede copiar el enlace, manténgalo presionado.'),
(165, 75, 'Pegue el enlace:', '¡Abre la herramienta TikTokio Viewer, pega el enlace y espera!'),
(166, 75, 'Complete el proceso:', 'El procesamiento comienza en unos segundos y ¡está listo para obtener lo que desea!'),
(167, 75, 'Ver en línea:', 'Toque el botón de reproducción para ver el perfil como espía, luego repita el proceso para otros formatos, como videos e historias.'),
(168, 76, 'Cari tiktok:', 'Buka laman web atau aplikasi Tiktok. Pilih profil, cerita, atau video di mana anda ingin menjadi pengintip! Pastikan anda mempunyai sambungan internet yang cepat dan pemilihannya betul.'),
(169, 76, 'Salin pautan:', 'Tekan \"Kongsi\" dan salin pautan untuk pemprosesan selanjutnya. Jika anda tidak dapat menyalin pautan, tekan dan tahan.'),
(170, 76, 'Tampal pautan:', 'Buka Tiktokio Viewer Tool, tampalkan pautan dan tunggu!'),
(171, 76, 'Lengkapkan proses:', 'Pemprosesan bermula dalam masa beberapa saat, dan anda sudah bersedia untuk mendapatkan apa yang anda mahukan!'),
(172, 76, 'Lihat dalam talian:', 'Ketik butang main untuk melihat profil sebagai mata -mata, kemudian ulangi proses untuk format lain, seperti video dan cerita.');

