INSERT INTO `language_mp3_titles` (`id`, `language_id`, `title`, `description`) VALUES
(60, 41, 'Find Tiktok Video:', 'Open the TikTok app and tap the video you want to convert to MP3. Tap the “Share” button in the bottom-right corner of the TikTok app. Now, click “Copy” to copy the video URL.'),
(123, 48, 'Trova il Tiktok che cosa vuoi convertire in MP3', 'Apri Tik Tok app e trova il video, che vuoi salvare come MP3. Vedrai Condivisione\' icona a destra dello schermo. Tocca Copia link nella schermata successiva.\r\n\r\nSe si utilizza un browser desktop (Chrome, Mozilla, Safari o altro), è possibile copiare facilmente il link dalla barra degli indirizzi del browser, quando si guarda un solo Tiktok.'),
(124, 48, 'Incolla il collegamento nella parte superiore della pagina.', 'Puoi farlo in qualsiasi pagina del sito.\r\n\r\nSe si utilizza un dispositivo mobile, toccare a lungo il modulo di input per incollare il link copiato. Se sei un utente desktop, è possibile incollare il link con la scorciatoia da tastiera Ctrl + V.\r\n\r\nQuasi fatto. Ora premere il pulsante \"Scaricare\".'),
(125, 48, 'Scarica Tik Tok MP3 nella pagina successiva', 'Se tutto è andato bene, una pagina \"risultati\" si aprirà. Scorrere verso il basso per visualizzare un collegamento Scarica MP3 nella parte inferiore della pagina.\r\n\r\nA volte può essere un link m4a invece di MP3. La maggior parte dei lettori multimediali può ora supportare m4a, poiché è parte integrante di mp4.\r\n\r\nA volte non sarà possibile visualizzare un collegamento audio. Questo significa che MP3 non è valutabile per questo certo Tiktok. Prova a trovarne un altro con musica simile. Stiamo lavorando a questo problema e sarà risolto presto.'),
(126, 41, 'Paste the Link:', 'You’ve now copied the URL of the TT video. Just open the TikTok MP3 converter and paste the link into it.'),
(127, 50, 'Téléchargeur de vidéos TikTok', 'Téléchargeur de vidéos TikTok'),
(128, 41, 'Complete the Process:', 'Now you’ll see the processing start, no extra step required. Just go ahead and follow the next steps.'),
(136, 41, 'Download MP3 Audio:', 'After downloading, you will see the “MP3 box.” Click on the “MP3 Button” and download the audio to your device.'),
(209, 70, 'العثور على فيديو Tiktok', 'افتح تطبيق TikTok واضغط على الفيديو الذي تريد تحويله إلى MP3. اضغط على زر \"مشاركة\" في الزاوية السفلية اليمنى من تطبيق TikTok. الآن، انقر على \"نسخ\" لنسخ رابط الفيديو.'),
(210, 70, 'الصق الرابط:', 'لقد نسخت الآن رابط الفيديو TT. ما عليك سوى فتح محول TikTok MP3 ولصق الرابط فيه.'),
(211, 70, 'أكمل العملية:', 'الآن سترى بدء التشغيل، لا يلزم أي خطوة إضافية. ما عليك سوى المتابعة واتباع الخطوات التالية.'),
(212, 70, 'تحميل ملف صوتي MP3', 'بعد التنزيل، سترى \"صندوق MP3\". انقر على \"زر MP3\" وقم بتنزيل الصوت إلى جهازك.'),
(213, 71, 'Tìm video trên Tiktok:', 'Mở ứng dụng TikTok và chạm vào video mà bạn muốn chuyển đổi thành định dạng MP3. Chạm vào nút “Chia sẻ” ở góc dưới bên phải của ứng dụng TikTok. Bây giờ, nhấp vào “Sao chép” để sao chép URL video.'),
(214, 71, 'Dán liên kết:', 'Bạn đã sao chép URL của video TT. Chỉ cần mở trình chuyển đổi TikTok MP3 và dán liên kết vào đó.'),
(215, 71, 'Hoàn thành quy trình', 'Bây giờ bạn sẽ thấy quá trình bắt đầu, không cần bất kỳ bước nào nữa. Chỉ cần tiếp tục và làm theo các bước tiếp theo.'),
(216, 71, 'Tải về âm thanh MP3:', 'Sau khi tải xuống, bạn sẽ thấy \"hộp MP3\". Nhấp vào nút \"MP3\" và tải âm thanh về thiết bị của bạn.'),
(217, 74, 'Temukan Video Tiktok:', 'Buka aplikasi TikTok dan ketuk video yang ingin Anda konversi ke MP3. Ketuk tombol \"Bagikan\" di pojok kanan bawah aplikasi TikTok. Sekarang, klik \"Salin\" untuk menyalin URL video.'),
(218, 74, 'Tempelkan Tautan:', 'Sekarang Anda telah menyalin URL video TT. Cukup buka konverter MP3 TikTok dan tempelkan tautan ke dalamnya.'),
(219, 74, 'Lengkapi Proses:', 'Sekarang Anda akan melihat proses dimulai, tidak diperlukan langkah ekstra. Lanjutkan dan ikuti langkah-langkah berikutnya.'),
(220, 74, 'Unduh Audio MP3:', 'Setelah mengunduh, Anda akan melihat \"kotak MP3.\" Klik tombol \"MP3\" dan unduh audio ke perangkat Anda.');

