INSERT INTO `language_stories_titles` (`id`, `language_id`, `title`, `description`) VALUES
(34, 41, 'Find Tiktok Story:', 'Open the Tiktok application and search for the photo or story that you liked most. You want to download? Press the \"Share\" button on the bottom right corner of the app and copy the URL.'),
(45, 48, 'Trova la storia di TikTok che vuoi salvare', 'Apri l\'app TT e trova la storia o la presentazione che desideri salvare come MP4. Vedrai un\'icona \"Condividi\" sulla destra dello schermo. Toccalo e quindi tocca \"Copia collegamento\" nella schermata successiva.\r\n\r\nSe utilizzi un browser desktop come Firefox, Safari o Google Chrome, puoi facilmente copiare il link dalla barra degli indirizzi del browser quando guardi una storia.'),
(46, 48, 'Incolla il link nella parte superiore della pagina.', 'Puoi utilizzare il nostro Tik Tok story downloader su qualsiasi pagina del sito. Scarica le storie o la presentazione di TikTok in mp4 assolutamente gratis e in pochi secondi!\r\n\r\nSe utilizzi un dispositivo mobile come un telefono Android o iOS, tocca a lungo il modulo di input per incollare il link copiato del downloader della storia di TikTok. Se sei un utente desktop, puoi incollare il collegamento con la scorciatoia da tastiera Ctrl+V.\r\n\r\nQuasi finito. Ora premi il pulsante e scarica la storia o la presentazione di TikTok.'),
(47, 50, 'Téléchargeur de vidéos TikTok', 'Téléchargeur de vidéos TikTok'),
(48, 41, 'Paste the Link:', 'Now you have copied the link of the story. Now jump to the TikTok story downloading tool and paste the link into the downloader tool. A smart way is to press CTRL+V with the keyboard. Great! You are done now!'),
(49, 41, 'Complete the Process:', 'Select the option to start the next step for download completion.'),
(50, 41, 'Download Tiktok Story Without Watermark:', 'You\'re near completing the process. Check down and you\'ll see different options. Choose one with the text \" No Watermark\". The download story without Watermark is done.'),
(131, 70, 'العثور على قصة Tiktok', 'افتح تطبيق Tiktok وابحث عن الصورة أو القصة التي أعجبتك أكثر. تريد تحميلها؟ اضغط على زر \"مشاركة\" في الزاوية السفلية اليمنى من التطبيق وانسخ عنوان URL.'),
(132, 70, 'الصق الرابط:', 'الآن لقد نسخت الرابط للقصة. الآن انتقل إلى أداة تنزيل القصص من تيك توك والصق الرابط في أداة التنزيل. الطريقة الذكية هي الضغط على CTRL + V على لوحة المفاتيح. رائع! لقد انتهيت الآن!'),
(133, 70, 'أكمل العملية.', 'حدد الخيار لبدء الخطوة التالية لاكتمال التنزيل.'),
(134, 70, 'تحميل قصة Tiktok بدون علامة مائية:', 'أنت على وشك إكمال العملية. تحقق من الأسفل وسترى خيارات مختلفة. اختر واحدة تحتوي على النص \"بدون علامة مائية\". تم تنزيل القصة بدون علامة مائية.'),
(135, 71, 'Tìm Tiktok Story:', 'Mở ứng dụng Tiktok và tìm kiếm bức ảnh hoặc câu chuyện mà bạn thích nhất. Bạn muốn tải xuống? Nhấn vào nút \"Chia sẻ\" ở góc dưới bên phải của ứng dụng và sao chép URL.'),
(136, 71, 'Dán Đường dẫn:', 'Bây giờ bạn đã sao chép liên kết của câu chuyện. Bây giờ chuyển đến công cụ tải câu chuyện TikTok và dán liên kết vào công cụ tải. Một cách thông minh là nhấn CTRL+V trên bàn phím. Tuyệt vời! Bạn đã hoàn thành rồi!'),
(137, 71, 'Hoàn thành quy trình.', 'Chọn tùy chọn để bắt đầu bước tiếp theo để hoàn tất việc tải xuống.'),
(138, 71, 'Tải về câu chuyện Tiktok không có dấu nước:', 'Bạn gần hoàn tất quy trình. Kiểm tra phía dưới và bạn sẽ thấy các tùy chọn khác nhau. Chọn một với văn bản \"Không có Watermark\". Việc tải xuống câu chuyện mà không có Watermark đã hoàn thành.'),
(139, 74, 'Cari Kisah Tiktok:', 'Buka aplikasi Tiktok dan cari foto atau cerita yang paling Anda sukai. Ingin mengunduh? Tekan tombol \"Bagikan\" di pojok kanan bawah aplikasi dan salin URL-nya.'),
(140, 74, 'Tempelkan Tautan:', 'Sekarang Anda telah menyalin tautan cerita. Sekarang beralih ke alat pengunduhan cerita TikTok dan tempelkan tautan ke dalam alat pengunduh. Cara cerdas adalah dengan menekan CTRL+V dengan keyboard. Hebat! Anda selesai sekarang!'),
(141, 74, 'Lengkapi Proses:', 'Pilih opsi untuk memulai langkah berikutnya untuk menyelesaikan pengunduhan.'),
(142, 74, 'Unduh Cerita Tiktok Tanpa Watermark:', 'Anda hampir menyelesaikan prosesnya. Periksa ke bawah dan Anda akan melihat berbagai pilihan. Pilih yang bertuliskan \"Tanpa Watermark\". Unduhan cerita tanpa Watermark sudah selesai.'),
(151, 75, 'Encuentra la historia de TikTok', 'Abre la aplicación de Tiktok y busca la foto o historia que más te gustó. ¿Quieres descargarla? Presiona el botón \"Compartir\" en la esquina inferior derecha de la aplicación y copia la URL.'),
(152, 75, 'Pegar el enlace:', 'Ahora has copiado el enlace de la historia. Ahora ve al herramienta de descarga de historias de TikTok y pega el enlace en la herramienta de descarga. Una forma inteligente es presionar CTRL+V en el teclado. ¡Genial! ¡Ya has terminado!'),
(153, 75, 'Completar el Proceso:', 'Seleccione la opción para iniciar el siguiente paso para completar la descarga.'),
(154, 75, 'Descargar Historia de TikTok Sin Marca de Agua:', 'Estás cerca de completar el proceso. Desplázate hacia abajo y verás diferentes opciones. Elige uno con el texto \"Sin marca de agua\". La descarga de la historia sin marca de agua está lista.'),
(155, 76, 'Cari Kisah Tiktok:', 'Buka aplikasi Tiktok dan cari foto atau cerita yang anda paling suka. Anda ingin memuat turun? Tekan butang \"Kongsi\" di sudut kanan bawah aplikasi dan salin URL.'),
(156, 76, 'Letak Pautan:', 'Sekarang anda telah menyalin pautan cerita itu. Sekarang, pergi ke alat muat turun cerita TikTok dan tampal pautan ke dalam alat muat turun. Cara pintar adalah dengan menekan CTRL+V dengan papan kekunci. Bagus! Anda sudah selesai sekarang!'),
(157, 76, 'Lengkapkan proses tersebut.', 'Pilih pilihan untuk memulakan langkah seterusnya bagi penyelesaian muat turun.'),
(158, 76, 'Muat turun Cerita Tiktok Tanpa Watermark:', 'Anda hampir lengkap dengan proses itu. Periksa ke bawah dan anda akan melihat pelbagai pilihan. Pilih satu dengan teks \"Tiada Tanda Air\". Muat turun cerita tanpa Tanda Air telah selesai.');

